public class RefundService
{
    public Refund ProcessRefund(Payment payment, decimal? amount = null)
    {
        if (payment.Status != PaymentStatus.Captured)
            throw new InvalidOperationException("Cannot refund uncaptured payment");

        var refundAmount = amount ?? payment.Amount;
        if (refundAmount > payment.Amount)
            throw new ArgumentException("Refund exceeds payment");

        var refund = new Refund
        {
            PaymentId = payment.Id,
            Amount = refundAmount,
            Status = RefundStatus.Processed
        };
        return refund;
    }
}

public class WebhookService
{
    private readonly Dictionary<string, int> _retryCount = new();

    public async Task DeliverAsync(string url, object payload)
    {
        string idempotencyKey = payload.IdempotencyKey;
        if (_retryCount.GetValueOrDefault(idempotencyKey) >= 5)
        {
            await _deadLetterQueue.EnqueueAsync(payload);
            return;
        }

        try
        {
            await _httpClient.PostAsync(url, content);
            _retryCount.Remove(idempotencyKey);
        }
        catch
        {
            _retryCount[idempotencyKey] = _retryCount.GetValueOrDefault(idempotencyKey) + 1;
            await _delayProvider.Delay(CalculateBackoff(_retryCount[idempotencyKey]));
        }
    }
}
